select distinct brand_name
from statistics
where date_format(order_date, #{periodType.dateFormat}) between date_format(#{startDate}, #{periodType.dateFormat}) and date_format(#{endDate}, #{periodType.dateFormat})

    and category_name in
    #{category}


    and brand_name in
    #{b}


    and order_status = #{orderStatus}

order by 1

select distinct date_format(order_date, #{periodType.dateFormat})
from statistics
where date_format(order_date, #{periodType.dateFormat}) between date_format(#{startDate}, #{periodType.dateFormat}) and date_format(#{endDate}, #{periodType.dateFormat})

    and category_name in
    #{category}


    and brand_name in
    #{b}


    and order_status = #{orderStatus}

order by 1

select cast(sum(coalesce(t.total_price, 0)) as decimal(38, 2)) as total_price
from (select distinct date_format(order_date, #{dto.periodType.dateFormat}) as order_date
      from statistics
      where date_format(order_date, #{dto.periodType.dateFormat}) between date_format(#{dto.startDate}, #{dto.periodType.dateFormat}) and date_format(#{dto.endDate}, #{dto.periodType.dateFormat})

    and category_name in
    #{category}


    and brand_name in
    #{b}


    and order_status = #{dto.orderStatus}

     ) d
left join (select total_price, quantity, order_date
           from statistics
           where date_format(order_date, #{dto.periodType.dateFormat}) between date_format(#{dto.startDate}, #{dto.periodType.dateFormat}) and date_format(#{dto.endDate}, #{dto.periodType.dateFormat})

    and category_name in
    #{category}


    and brand_name in
    #{b}


    and order_status = #{dto.orderStatus}


    and brand_name = #{brand}

          ) t
  on date_format(t.order_date, #{dto.periodType.dateFormat}) = d.order_date
group by d.order_date
order by d.order_date

select cast(sum(coalesce(t.quantity, 0)) as char) as quantity
from (select distinct date_format(order_date, #{dto.periodType.dateFormat}) as order_date
      from statistics
      where date_format(order_date, #{dto.periodType.dateFormat}) between date_format(#{dto.startDate}, #{dto.periodType.dateFormat}) and date_format(#{dto.endDate}, #{dto.periodType.dateFormat})

    and category_name in
    #{category}


    and brand_name in
    #{b}


    and order_status = #{dto.orderStatus}

     ) d
left join (select total_price, quantity, order_date
           from statistics
           where date_format(order_date, #{dto.periodType.dateFormat}) between date_format(#{dto.startDate}, #{dto.periodType.dateFormat}) and date_format(#{dto.endDate}, #{dto.periodType.dateFormat})

    and category_name in
    #{category}


    and brand_name in
    #{b}


    and order_status = #{dto.orderStatus}


    and brand_name = #{brand}

          ) t
  on date_format(t.order_date, #{dto.periodType.dateFormat}) = d.order_date
group by d.order_date
order by d.order_date
